    def _pick_rollout_defaults(artifact):
        """Choose default staging parameters for an artifact entering the environment."""
        if not artifact_promotable(artifact):
            return STAGED_DEFAULTS
        return PROMOTED_DEFAULTS

    def resolve_rollout_environment(artifact):
        """Return the environment config used when a worker enters an artifact into staging."""
        defaults = _pick_rollout_defaults(artifact)
        return build_environment(defaults, artifact)
